def solve_prefix(n):
    if n == 0:
        return 0

    def digit_sum_count(n):
        if n == 0:
            return 0

        s = 0
        power = 1
        while n // power == 0:
            power *= 10

        digit_sum = 0
        while power >= 1:
            d = n // power
            less_than = n % power
            if power <= n:
                digit_sum += (d * (d - 1) // 2) * power
                digit_sum += d * ((n // power) + 1) if n >= d * power else d
                digit_sum += d * power
            n //= power
            power //= 10

        s = digit_sum
        return s

    return digit_sum_count(n)

