def solution(input_str):
    lines = input_str.strip().split('\n')
    n, m = map(int, lines[0].split())

    segments = []
    current_segment = []
    friend_map = {}
    friend_idx = 0

    def get_friend_index(name):
        if name not in friend_map:
            friend_map[name] = friend_idx
            friend_idx += 1
        return friend_map[name]

    for i in range(1, n + 1):
        if i >= len(lines):
            break
        parts = lines[i].split()
        event_type = parts[0]
        if event_type == '1':
            if current_segment:
                segments.append(current_segment)
                current_segment = []
        else:
            friend_name = parts[1]
            current_segment.append(get_friend_index(friend_name))

    if current_segment:
        segments.append(current_segment)

    num_friends = len(friend_map)
    conflicts = [set() for _ in range(num_friends)]

    for seg in segments:
        unique_in_seg = set(seg)
        for u in unique_in_seg:
            for v in unique_in_seg:
                if u != v:
                    conflicts[u].add(v)
                    conflicts[v].add(u)

    best = 0
    for mask in range(1 << num_friends):
        valid = True
        for i in range(num_friends):
            if (mask >> i) & 1:
                for j in conflicts[i]:
                    if (mask >> j) & 1:
                        valid = False
                        break
            if not valid:
                break
        if valid:
            best = max(best, bin(mask).count('1'))

    return str(best)

