def backtrack(current_a, k, ops=[], target=1):
    n = len(current_a)
    if n == 1:
        if current_a[0] == target:
            return True
        else:
            return False

    for i in range(n):
        for j in range(i + 1, n):
            x = current_a[i]
            y = current_a[j]
            z = f(x + y, k)

            new_a = current_a[:i] + current_a[i+1:j] + [z] + current_a[j+1:]
            new_ops = ops.copy()
            new_ops.append((x, y))

            if backtrack(new_a, k, new_ops, target):
                return True

            # Backtrack doesn't need to explicitly undo since we create new_a each time
    return False

def solution(input_str):
    n, k, a = parse_input(input_str)
    initial_a = a.copy()

    if backtrack(initial_a, k):
        backtrack(initial_a, k).__exit__ = lambda self: None  # Help to make ops accessible
        # We need a way to return the ops, let me refactor
        return "NO"

    # Let me rewrite properly to return operations
    best_ops = None

    def backtrack_ops(current_a, k, ops_list):
        nonlocal best_ops
        result = []
        n = len(current_a)
        if n == 1:
            if current_a[0] == 1:
                result = ops_list
                return result
            return None

        for i in range(n):
            for j in range(i + 1, n):
                x = current_a[i]
                y = current_a[j]
                z = f(x + y, k)

                new_a = current_a[:i] + current_a[i+1:j] + [z] + current_a[j+1:]
                new_ops = ops_list + [(x, y)]
                result = backtrack_ops(new_a, k, new_ops)
                if result is not None:
                    return result
        return None

    best_ops = backtrack_ops(initial_a, k, [])

    if best_ops is None:
        return "NO"

    output = ["YES"]
    for x, y in best_ops:
        output.append(f"{x} {y}")
    return "\n".join(output)

