    def parse_test_case(lines_list):
        if not lines_list:
            return None

        # The first line might be empty
        while lines_list and not lines_list[0].strip():
            lines_list = lines_list[1:]

        if not lines_list:
            return None

        try:
            n = int(lines_list[0])
            lines_list = lines_list[1:]

            nodes = []
            for i in range(n):
                while lines_list and not lines_list[0].strip():
                    lines_list.pop(0)
                parts = list(map(int, lines_list[0].split()))
                lines_list.pop(0)
                if parts[0] == -1:
                    nodes.append({'type': 'internal', 'left': parts[1], 'right': parts[2]})
                else:
                    nodes.append({'type': 'leaf', 'value': parts[0]})
            return nodes
        except:
            return None

    def get_subtree_leaves(node):
        if node['type'] == 'leaf':
            return {'leaves': [node['value']], 'subtree_size': 1}
        else:
            left = get_subtree_leaves(node['left'])
            right = get_subtree_leaves(node['right'])
            return {
                'leaves': left['leaves'] + right['leaves'],
                'subtree_size': left['subtree_size'] + right['subtree_size']
            }

    # For each node, compute the game-theoretic value
    def compute_game_value(node):
        if node['type'] == 'leaf':
            return node['value']

        left_val = compute_game_value(node['left'])
        right_val = compute_game_value(node['right'])

        left_leaves = get_subtree_leaves(node['left'])
        right_leaves = get_subtree_leaves(node['right'])
        left_size = left_leaves['subtree_size']
        right_size = right_leaves['subtree_size']

        total_leaves_in_children = left_size + right_size
        total_moves = total_leaves_in_children - 1  # number of merges needed

        # If total_moves is odd, Pieguy makes the last move (maximizes)
        # If total_moves is even, Piegirl makes the last move (minimizes)

        if total_moves % 2 == 1:
            # Pieguy controls - he wants to maximize
            return max(left_val, right_val)
        else:
            # Piegirl controls - she wants to minimize
            return min(left_val, right_val)

    # Process all test cases
    if not lines:
        return ""

    t = int(lines[0])
    idx = 1
    output = []

    for _ in range(t):
        # Skip empty lines
        while idx < len(lines) and not lines[idx].strip():
            idx += 1

        if idx >= len(lines):
            break

        # Get next test case
        tc_lines = []
        while idx + 1 < len(lines) and (not lines[idx].strip() or lines[idx+1].strip().startswith('f')):
            tc_lines.append(lines[idx])
            idx += 1
        if not tc_lines:
            break

        # Actually, let's skip empty lines and next line is n
        while idx < len(lines) and not lines[idx].strip():
            idx += 1

        if idx >= len(lines):
            break

        n = int(lines[idx])
        idx += 1

        nodes = []
        for i in range(n):
            parts = list(map(int, lines[idx].split()))
            idx += 1
            if parts[0] == -1 and len(parts) >= 3:
                nodes.append({'type': 'internal', 'left': parts[1], 'right': parts[2]})
            else:
                nodes.append({'type': 'leaf', 'value': parts[0]})

        result = compute_game_value(nodes[0])
        output.append(str(result))

    return '\n'.join(output)


