def solution(input_str):
    a, b, k, t = map(int, input_str.strip().split())
    MOD = 10**9 + 7

    # We need to count games where Memory's final score > Lexa's final score
    # Memory starts with a, Lexa starts with b
    # After t turns: Memory = a + sum(x_i), Lexa = b + sum(y_i)
    # where each x_i, y_i ∈ [-k, k]
    # We want: a + sum(x_i) > b + sum(y_i)
    # This is equivalent to: sum(x_i - y_i) > b - a

    # For each turn, d = x - y, where x, y ∈ [-k, k]
    # d ∈ [-2k, 2k], and count[d] = 2k + 1 - |d|
    # We need distribution of sum of t independent such variables

    # Build distribution using DP
    # dp[s] = number of ways to get sum s

    OFFSET = t * 2 * k
    dp = {0: 1}

    # Precompute single turn differences
    single_turn = {}
    for d in range(-2 * k, 2 * k + 1):
        single_turn[d] = 2 * k + 1 - abs(d)

    for _ in range(t):
        new_dp = {}
        for s, count in dp.items():
            for d, ways in single_turn.items():
                if (s + d) not in new_dp:
                    new_dp[s + d] = 0
                new_dp[s + d] = (new_dp[s + d] + count * ways) % MOD
        dp = new_dp

    # Count ways where sum > b - a
    ans = 0
    for s, count in dp.items():
        if s > b - a:
            ans = (ans + count) % MOD

    return str(ans) + '\n'


