    for i in range(3, 3 + m):
        act, team = lines[i].split()
        actions.append((act, int(team)))

    strengths.sort(reverse=True)
    MAX_M = m

    @lru_cache(maxsize=None)
    def dp(action_idx, mask):
        if action_idx == m:
            return 0

        act, team = actions[action_idx]

        if act == 'p':
            max_val = float('-inf')
            for i in range(MAX_M):
                if not (mask & (1 << i)):
                    val = dp(action_idx + 1, mask | (1 << i)) + (strengths[i] if team == 1 else -strengths[i])
                    max_val = max(max_val, val)
            return max_val
        else:
            min_val = float('inf')
            for i in range(MAX_M):
                if not (mask & (1 << i)):
                    val = dp(action_idx + 1, mask | (1 << i))
                    min_val = min(min_val, val)
            return min_val

    return f"{dp(0, 0)}\n"

