        # - If S[k] == T[k], no pairing needed (self-match)
        # - If S[k] != T[k], then S[k] and T[k] must form a valid pair
        # - Each character appears in at most one pair
        # - The mapping must be symmetric (if x maps to y, then y maps to x)

        mapping = {}
        valid = True

        for j in range(m):
            x = S[i + j]
            y = T[j]

            if x == y:
                # Self-match, no pairing needed
