            # x and y are different, must form a pair
            if x in mapping:
                # x is already mapped, must map to y
                if mapping[x] != y:
                    valid = False
                    break
            else:
                mapping[x] = y

            if y in mapping:
                # y is already mapped, must map back to x
                if mapping[y] != x:
                    valid = False
                    break
            else:
                mapping[y] = x

        if valid:
            result.append(i + 1)  # 1-indexed position

    result.sort()
