        edges.append((u, v))
        adj[u].append(v)
        adj[v].append(u)

    # Use Tarjan's algorithm to find bridges
    discovery = [0] * (n + 1)
    low = [0] * (n + 1)
    visited = [False] * (n + 1)
    time = [1]
    bridges = []

    def dfs_bridge(u, p=None):
        visited[u] = True
        discovery[u] = low[u] = time[0]
        time[0] += 1

        for v in adj[u]:
            if v == p:
                continue
            if visited[v]:
                low[u] = min(low[u], discovery[v])
            else:
                dfs_bridge(v, u)
                low[u] = min(low[u], low[v])
                if low[v] > discovery[u]:
                    bridges.append((min(u, v), max(u, v)))

    dfs_bridge(1)

    if bridges:
        return "0"

    # Graph is 2-edge-connected, now orient edges for strong connectivity
    # DFS approach: orient tree edges from parent to child
    # Back edges from child to parent (ancestor)

    visited = [False] * (n + 1)
    depth = [0] * (n + 1)
    edge_orientation = {}
    timer = [1]

    def dfs_visit(u):
        visited[u] = True
        depth[u] = timer[0]
        timer[0] += 1

        for v in adj[u]:
            if visited[v]:
                if depth[v] > depth[u]:
                    continue
                # Back edge or cross edge
                edge_orientation[(u, v)] = (u, v)
            else:
                depth[v] = depth[u] + 1
                edge_orientation[(v, u)] = (v, u)
                dfs_visit(v)

    dfs_visit(1)

    # Build result by orienting each original edge
    edge_idx_map = {}
    for idx, (u, v) in enumerate(edges):
        if u in edge_idx_map:
            edge_idx_map[u].append(idx)
        else:
            edge_idx_map[u] = [idx]
        edge_idx_map[v].append(idx)

    # For simplicity, use DFS tree depth to determine orientation
    visited = [False] * (n + 1)
    parent = [0] * (n + 1)
    depth = [0] * (n + 1)
    dfs_parent_map = {}

    timer = [1]

    def dfs_parent_map(u, p, d):
        visited[u] = True
        parent[u] = p
        depth[u] = d
        dfs_parent_map[u] = p

        for v in adj[u]:
            if not visited[v]:
                dfs_parent_map(v, u, d + 1)

    dfs_parent_map(1, 0, 0)

    result = []
    for u, v in edges:
        if parent[v] == u:
            # Tree edge: u -> v
            result.append(f"{u} {v}")
        elif parent[u] == v:
            # Tree edge: v -> u
            result.append(f"{v} {u}")
        else:
            # Back/cross edge: orient based on depth
            # Heuristic: align with DFS direction
            if depth[u] <= depth[v]:
                result.append(f"{u} {v}")
            else:
                result.append(f"{v} {u}")

    return "\n".join(result)


