def solution(input_str):
    if not input_str.strip():
        return '-1\n'

    lines = input_str.strip().split('\n')
    if len(lines) < 1:
        return '-1\n'

    v_c_str = lines[0].strip()
    l = len(v_c_str)

    if len(lines) < 2:
        return '-1\n'

    try:
        parts = lines[1].strip().split()
        n, m = int(parts[0]), int(parts[1])
    except:
        return '-1\n'

    # Parse rules
    rules = []
    start_rule_line = 2
    end_rule_line = min(start_rule_line + m, len(lines))

    for i in range(start_rule_line, end_rule_line):
        line = lines[i].strip()
        if line:
            parts = line.split()
            if len(parts) >= 4:
                try:
                    pos1, pos2 = int(parts[0]), int(parts[2])
                    t1, t2 = parts[1], parts[3]
                    rules.append((pos1, t1, pos2, t2))
                except:
                    pass

    # Get s (might be the last line)
    if len(lines) > end_rule_line:
        s = lines[len(lines) - 1].strip()
    else:
        return '-1\n'

    if len(s) != n:
        return '-1\n'

    s_list = list(s)

    # Characters: 'a'...'a'+l-1
    alphabet = list(string.ascii_lowercase[:l])

    def is_vowel(char_code):
        """Returns True if character with code char_code is a vowel"""
        if char_code < l:
            return v_c_str[char_code] == 'V'
        return False

    def check(assignment):
        """Check if a word satisfies all rules"""
        for pos1, t1, pos2, t2 in rules:
            # pos1, pos2 are 1-indexed
            p1, p2 = pos1 - 1, pos2 - 1

            if p1 >= n or p2 >= n:
                continue

            w1, w2 = assignment[p1], assignment[p2]

            # Check type of position p1
            t1_is_vowel = (t1 == 'V')
            w1_is_vowel = is_vowel(w1)

            # Rule: if pos1 has type t1, then pos2 has type t2
            if w1_is_vowel == t1_is_vowel:
                t2_is_vowel = (t2 == 'V')
                w2_is_vowel = is_vowel(w2)
                if w2_is_vowel != t2_is_vowel:
                    return False
        return True

    # First check if s itself is valid
    if check(s_list):
        return s

    # Find next valid word >= s
    # Try changing at different positions, keep prefix, increase current position

    best_result = None

    def try_fill_from(pos, current_word):
        """Try to fill positions from pos onwards, returning a valid word if exists"""
        nonlocal best_result

        if best_result is not None:
            return None

        if pos == n:
            if check(current_word):
                best_result = list(current_word)
                return current_word[:]
            return None

        # If current_word < s lexicographically, we need to change position
        if current_word < s_list and pos < n and check(current_word[:pos] + [s_list[pos]]):
            # Try to increase at position pos
            for idx in range(ord(s_list[pos]), ord('z') + 1):
                char = chr(idx)
                if char in alphabet and char >= alphabet[0]:
                    new_word = current_word[:]
                    new_word[pos] = char
                    if try_fill_from(pos + 1, new_word):
                        return new_word
            return None

        # Build word greedily with smallest possible choices
        for idx in range(len(alphabet)):
            new_word = current_word[:]
            new_word[pos] = alphabet[idx]

            # Fill rest with smallest char
            tail = [alphabet[0]] * (n - pos - 1)

            candidate = new_word + tail
