                if best_result is None or candidate < ''.join(best_result):
                    best_result = candidate[:]
                if best_result == candidate[:]:
                    best_result = candidate[:]
                    return candidate[:]

        return None

    result = try_fill_from(0, s_list)

    if result is not None and check(result):
        return ''.join(result)

    return '-1\n'

