    if n == 2:
        return str((r - l + 1) * (r - l) + '\n')

    ans = 0

    # For n >= 3, find all valid (p, q) pairs where p > q and gcd(p,q) = 1
    # Start with q = 1 and find max q such that q^(n-1) <= r
    q = 1
    while True:
        try:
            q_pow = q ** (n - 1)
        except:
            break
        if q_pow > r:
            break
        q += 1
