    for current_q in range(1, maxq + 1):
        q_pow = current_q ** (n - 1)

        # p^(n-1) * l / q^(n-1) <= r
        # Therefore: p^(n-1) <= r * q^(n-1) / l
        max_p_pow = r * q_pow // l

        # Binary search for maximum valid p
        low, high = 1, r
        max_p = 1

        while low <= high:
            mid = (low + high) // 2
            try:
                mid_pow = mid ** (n - 1)
            except:
                high = mid - 1
                continue

            if mid_pow <= max_p_pow:
                max_p = mid
                low = mid + 1
            else:
                high = mid - 1

        # Skip if p <= q (we need p > q for d > 1)
