def count_paths(pos, k_left, m, visited_set, n):
    """
    Count number of valid paths of length k_left starting from pos
    visited_set contains all planets already visited (including pos)
    """
    if k_left == 0:
        return 1

    # Create a state key for memoization
    # We hash the visited set to a tuple frozenset for memoization
    state = (k_left, pos, frozenset(visited_set))

    if state in memo:
