    # Try all possible next positions
    for next_pos in range(1, min(pos + m, n) + 1):
        if next_pos not in visited_set:
            new_visited = visited_set.union({next_pos})
            result = (result + count_paths(next_pos, k_left - 1, m, new_visited, n)) % MOD

    memo[state] = result
    return result

