def solution(input_str):
    """
    Determines if we can place m roads between n cities on a ring such that
    roads don't cross (grouped as all inside or all outside), and returns
    whether each road should be inside ('i') or outside ('o').
    """
    lines = input_str.strip().split('\n')
    n, m = map(int, lines[0].split())
    pairs = []
    for i in range(1, m + 1):
        u, v = map(int, lines[i].split())
        pairs.append((u, v))

    def is_between(p, a, b, n):
        """Check if p is strictly between a and b going clockwise."""
        start_to_end = (b - a + n) % n
        start_to_point = (p - a + n) % n
        return start_to_point > 0 and start_to_point < start_to_end

    def paths_cross(p1, p2, p3, p4, n):
        """Check if two chords (p1,p2) and (p3,p4) cross on the ring."""
        return (is_between(p3, p1, p2, n) and not is_between(p4, p1, p2, n)) or \
               (not is_between(p3, p1, p2, n) and is_between(p4, p1, p2, n))

    # Build intersection graph where edges connect crossing roads
    graph = [[] for _ in range(m)]
    for i in range(m):
        for j in range(i + 1, m):
            if paths_cross(pairs[i][0], pairs[i][1], pairs[j][0], pairs[j][1], n):
                graph[i].append(j)
                graph[j].append(i)

    # Check if graph is bipartite (can be 2-colored)
    color = {}
    possible = True

    def dfs(node, c):
        color[node] = c
        for neighbor in graph[node]:
            if neighbor not in color:
                if not dfs(neighbor, 1 - c):
                    return False
            elif color[neighbor] == c:
                return False
        return True

    for i in range(m):
        if i not in color:
            if not dfs(i, 0):
                possible = False
                break

    if not possible:
        return "Impossible"

    # Build result string
    res = []
    for i in range(m):
        res.append('i' if color[i] == 0 else 'o')
    return ''.join(res)


