def solution(s):
    """
    Computes f(x, y) where f(a, 0) = 0 and f(a, b) = 1 + f(a, b - gcd(a, b))

    The key insight is:
    1. When b % gcd(a, b) == 0, we can compute steps directly as b // gcd(a, b)
    2. When b % gcd(a, b) != 0, we need to find where gcd changes next
    """
    x, y = map(int, s.split())

    if y == 0:
        return "0"

    # Compute gcd of x and y
    g = gcd(x, y)

    # If y is a multiple of gcd, we can reach 0 in exactly y // gcd steps
    if y % g == 0:
        return str(y // g)

    # Otherwise, find the next transition point where gcd changes
    # We search for smallest k > 0 where gcd(x, y - k*g) > g
    min_k = y // g + 1
    next_k = float('inf')
    next_b = -1

    # For each k, check if gcd changes at y - k*g
    # Instead of naive iteration, we can batch by finding where gcd(x, val) > g
    # where val = y - k*g

    # Check transition points efficiently
    k = 1
    while y - k * g >= 0:
        val = y - k * g
        if val > 0:
            new_g = gcd(x, val)
            if new_g > g:
                next_k = k
                next_b = val
                break
            k += 1
        else:
            # We've reached b = 0
            next_k = k
            next_b = 0
            break

    ans = 0
    # Accumulate steps
    while y > 0:
        g = gcd(x, y)
        # Find next transition point
        if y % g == 0:
            steps = y // g
            return str(ans + steps)

        # Find transition
        for k in range(1, y // g + 2):
            val = y - k * g
            if val == 0:
                return str(ans + k)
            if gcd(x, val) > g:
                ans += k
                y = val
                break
        else:
            return str(ans + y // g)

    return str(ans)


