        if len(A) == 1 or len(B) == 1:
            return ((A[0] * B[0]) % MOD,) if len(B) == 1 else ((A[0] * B[0]) % MOD,)

        C = [0] * (len(A) + len(B) - 1)
        for i in range(len(A)):
            for j in range(len(B)):
                C[i + j] = (C[i + j] + A[i] * B[j]) % MOD
        return C

    def poly_integral(A):
        total = 0
        for i, coeff in enumerate(A):
            total = (total + coeff * inverse(i + 1)) % MOD
        return total

