                fail[nxt] = trie[fail[curr]][c]
                # Merge patterns from failure link
                patterns[nxt] = sorted(set(patterns[nxt] + patterns[fail[nxt]]))
                queue.append(nxt)
            else:
                trie[curr][c] = trie[fail[curr]][c]

    from functools import lru_cache

    @lru_cache(maxsize=None)
    def dp(pos, node, profile):
        """
        dp[pos][node][profile]
        pos: current position in string (0 to n-1)
        node: current state in AC automaton
        profile: tuple where profile[k] stores the position up to which position (pos-k+1) is covered from matches
        """
        if pos == n:
            return 1

        total = 0
        for c in range(4):
            next_node = trie[node][c]

            # Update profile with patterns that end at position pos
            new_profile = list(profile)
            for L in patterns[next_node]:
                if L <= 10:
                    new_profile[L] = max(new_profile[L], pos + 1)

            # Check if positions 0 to pos-1 are covered
            valid = True
            for k in range(1, 11):
                if 0 <= pos - k < pos:
                    # Position (pos - k + 1) needs to be covered
                    # Need profile[k] >= pos - k + 1
                    if new_profile[k] < pos - k + 1:
                        valid = False
                        break

            if valid:
                next_profile = tuple(max(0, x - 1) for x in new_profile)
                total = (total + dp(pos + 1, next_node, next_profile)) % MOD

        return total

    initial_profile = tuple([0] * 11)
    result = dp(0, 0, initial_profile)
    return str(result)

