def is_bitonic(arr):
    """Check if array is bitonic (increases then decreases)"""
    n = len(arr)
    if n <= 1:
        return True

    # Find peak
    peak = 0
    for i in range(1, n):
        if arr[i] > arr[peak]:
            peak = i
        else:
            break

    # Check left side increases to peak
    for i in range(peak - 1, -1, -1):
        if arr[i] >= arr[i+1]:
            return False

    # Check right side decreases from peak
    for i in range(peak, n - 1):
        if arr[i] <= arr[i+1]:
            return False

    return True


def build_bitonic_matrix(n, m, row_maxes, col_maxes):
    all_nums = set(range(1, n * m + 1))

    # Place n*m at position that works for both
    # Sort row/max indices and place strategically
    sorted_row_indices = sorted(range(n), key=lambda i: row_maxes[i], reverse=True)
    sorted_col_indices = sorted(range(m), key=lambda j: col_maxes[j], reverse=True)

    positions = set()
    row_max_positions = {}
    col_max_positions = {}

    # Place row maximums and col maximums at appropriate positions
    for i, idx in enumerate(sorted_row_indices):
        row_max_positions[i] = (i, 0)
        for c in range(m):
            if (i, c) not in positions:
                positions.add((i, c))
                break

    for j, idx in enumerate(sorted_col_indices):
        col_max_positions[j] = (0, j)
        for r in range(n):
            if (r, j) not in positions:
                positions.add((r, j))
                break

    result = [[0] * m for _ in range(n)]

    # Place global max first
    result[0][0] = n * m

    used = {n * m}

    # Fill remaining positions in a way that satisfies bitonicity
    # Process by row, filling row by row with sorted values
    remaining = sorted(all_nums - used, reverse=True)

    row_pos_limitations = {}
    for r in range(n):
        for c in range(m):
            row_pos_limitations[(r, c)] = (n * m if r == 0 else row_maxes[r] if (r, c) == row_max_positions.get(r) else 0, 
                                              col_maxes[c] if c == 0 else col_maxes[c])

    # Simple fill: each row gets values in decreasing order, each column too
    idx = 0
    for r in range(n):
        start = n * m - (idx % m) + ((n - 1 - r) * m)
        for c in range(m):
            val = remaining[idx]
            result[r][c] = val
            used.add(val)
            idx += 1

    # Verify bits are okay and return
    for r in range(n):
        if not is_bitonic(result[r]):
            return None

    # Check column bits
    for c in range(m):
        col_vals = [result[r][c] for r in range(n)]
        if not is_bitonic(col_vals):
            return None

    return result


