import math
from itertools import combinations

class Circle:
    def __init__(self, cx, cy, r):
        self.cx = cx
        self.cy = cy
        self.r = r

    def __lt__(self, other):
        return self.r < other.r

EPS = 1e-9

def circumcircle(p1, p2, p3):
    x1, y1 = p1
    x2, y2 = p2
    x3, y3 = p3
    d = 2 * (x1 * (y2 - y3) + x2 * (y3 - y1) + x3 * (y1 - y2))
    if abs(d) < 1e-9:
        dist_01 = ((x1-x2)**2 + (y1-y2)**2) ** 0.5
        dist_12 = ((x1-x3)**2 + (y1-y3)**2) ** 0.5
        dist_23 = ((x2-x3)**2 + (y2-y3)**2) ** 0.5
        max_dist = max(dist_01, dist_12, dist_23)
        if max_dist < 1e-9:
            return Circle(x1, y1, 0)
        mid = (x1 + x3) / 2 if max_dist == dist_01 else (x2 + x3) / 2 if max_dist == dist_12 else (x1 + x2) / 2
        cy = (y1 + y3) / 2 if max_dist == dist_01 else (y2 + y3) / 2 if max_dist == dist_12 else (y1 + y2) / 2
        return Circle(mid, cy, max_dist)
    ux = ((x1**2 + y1**2) * (y2 - y3) + (x2**2 + y2**2) * (y3 - y1) + (x3**2 + y3**2) * (y1 - y2)) / d
    uy = ((x1**2 + y1**2) * (x3 - x2) + (x2**2 + y2**2) * (x1 - x3) + (x3**2 + y3**2) * (x2 - x1)) / d
    r2 = (ux - x1)**2 + (uy - y1)**2
    return Circle(ux, uy, math.sqrt(r2))

def circle_from_two(p1, p2):
    cx = (p1[0] + p2[0]) / 2
    cy = (p1[1] + p2[1]) / 2
    r = ((p1[0] - p2[0]) ** 2 + (p1[1] - p2[1]) ** 2) ** 0.5
    return Circle(cx, cy, r)

def circle_from_one(p1):
    return Circle(p1[0], p1[1], 0, p1)

def min_enclosing_circle_rec(points, boundary):
    """Recursive step for well z' algorithm"""
    if len(boundary) == 3:
        return circumcircle(boundary[0], boundary[1], boundary[2])
    elif len(boundary) == 2:
        return circle_from_two(boundary[0], boundary[1])
    elif len(boundary) == 1:
        return circle_from_one(boundary[0])

    cx, cy, r = min_enclosing_circle_rec(points[:-1], [])

    if len(points) < 1:
        return cx, cy, r

    p = points[-1]
    max_dist = ((p[0] - cx)**2 + (p[1] - cy)**2) ** 0.5

    if max_dist <= r + EPS:
        return cx, cy, r

    return min_enclosing_circle_rec(list(points), [p])

def min_enclosing_circle(points):
    if not points:
        return Circle(0, 0, 0)

    # Shuffle for better performance
    points = list(points)
    result = min_enclosing_circle_rec(points, [])
    return result

def get_intersections(circles, T):
    """Find all intersection points of circles with radius T"""
    points = set()
    for i, j in combinations(circles, 2):
        c1, c2 = i, j
        cx1, cy1 = c1
        cx2, cy2 = c2
        d2 = (cx1 - cx2)**2 + (cy1 - cy2)**2

        if d2 == 0:
            continue

        d = math.sqrt(d2)

        if d > 2 * T:
            continue

        midx = (cx1 + cx2) / 2.0
        midy = (cy1 + cy2) / 2.0

        calc_d2 = T * T - (d * d) / 4.0
        if calc_d2 < 0:
            calc_d2 = 0
        calc_h = math.sqrt(calc_d2)

        if calc_h < EPS:
            points.add((midx, midy))
        else:
            perp = (-(cy2 - cy1), cx2 - cx1)
            perp_len = math.sqrt(perp[0]**2 + perp[1]**2)
            if perp_len > EPS:
                factor = calc_h / perp_len
                px1 = midx + perp[0] * factor
                py1 = midy + perp[1] * factor
                px2 = midx - perp[0] * factor
                py2 = midy - perp[1] * factor
                points.add((px1, py1))
                points.add((px2, py2))

    return list(points)

def welzl_algorithm(points, boundary):
    if not boundary:
        return []

    cx, cy, r = min_enclosing_circle(boundary)
    return [cx, cy, r]

