def solution(input_str):
    """
    Divide n distinct integers into two sets A and B such that:
    - If x in A, then a-x must also be in A
    - If x in B, then b-x must also be in B

    Returns "YES" followed by assignments, or "NO" if impossible.
    """
    lines = input_str.strip().split('\n')
    n, a, b = map(int, lines[0].split())
    p = list(map(int, lines[1].split()))

    # Map values to indices for O(1) lookup
    val_to_idx = {val: i for i, val in enumerate(p)}

    # Build chain from a given start: follow A-complements
    def build_a_chain(start):
        chain = []
        visited = set()
        curr = start
        while True:
            if curr in visited:
                break
            visited.add(curr)
            chain.append(curr)
            comp = a - p[curr]
            if comp in val_to_idx and val_to_idx[comp] not in visited:
                curr = val_to_idx[comp]
            else:
                break
        return chain

    def build_b_chain(start):
        chain = []
        visited = set()
        curr = start
        while True:
            if curr in visited:
                break
            visited.add(curr)
            chain.append(curr)
            comp = b - p[curr]
            if comp in val_to_idx and val_to_idx[comp] not in visited:
                curr = val_to_idx[comp]
            else:
                break
        return chain

    # Track assignments (0=unassigned, 1=A, 2=B)
    assign = [0] * n

    # Track which nodes were assigned during each chain exploration
    for i in range(n):
        if assign[i] != 0:
            continue

        a_chain = build_a_chain(i)
        b_chain = build_b_chain(i)

        # Determine chain type: 
        # - If a-chain allows pure A assignment (no B-complement conflicts), prefer A
        # - If b-chain allows pure B assignment, prefer B

        can_be_pure_A = True
        can_be_pure_B = True

        for idx in a_chain:
            # If element in A-chain has a B-complement that's in input, 
            # we'd need that in A, which is OK if B-complement can be in A
            # If B-complement is NOT in input, element cannot be in A
            b_comp = b - p[idx]
            if b_comp not in val_to_idx:
                can_be_pure_A = False

        for idx in b_chain:
            # Similar logic for B-chain and A-complement
            a_comp = a - p[idx]
            if a_comp not in val_to_idx:
                can_be_pure_B = False

        # Choose based on validity
        if not can_be_pure_A and can_be_pure_B:
            # Must be B
            for idx in b_chain:
                assign[idx] = 2
            # Mark all in b_chain as visited
            for idx in b_chain:
                if assign[idx] == 0:
                    assign[idx] = 2
        elif not can_be_pure_B and can_be_pure_A:
            # Must be A
            for idx in a_chain:
                assign[idx] = 1
            for idx in a_chain:
                if assign[idx] == 0:
                    assign[idx] = 1
        else:
            # Both possible - choose A (arbitrary, but need to handle all cases)
            # However, some elements might need special handling
            for idx in a_chain:
                # Check if this index was already visited during B processing
                if assign[idx] != 0:
                    continue
                assign[idx] = 1

            # Also check b_chain
            remaining_b_chain = [idx for idx in b_chain if assign[idx] == 0]
            # If there are remaining in b_chain, they must also be A or B
            for idx in remaining_b_chain:
                # Check if this forcing breaks anything
                can_be_A = not any(
                    (b - p[idx]) in val_to_idx and 
                    val_to_idx[b - p[idx]] != idx
                )
                if not can_be_A:
                    return "NO"
                assign[idx] = 1

    # Verify assignment is valid
    for i in range(n):
        val = assign[i]
        if val == 0:
            return "NO"

        x = p[i]
        if val == 1:  # Set A - need a-x in A
            comp = a - x
            if comp in val_to_idx:
                j = val_to_idx[comp]
                if assign[j] == 0 or assign[j] != 1:
                    return "NO"
        else:  # Set B - need b-x in B
            comp = b - x
            if comp in val_to_idx:
                j = val_to_idx[comp]
                if assign[j] == 0 or assign[j] != 2:
                    return "NO"

    # Convert: 1->0 (A), 2->1 (B) for output
    output = [0 if x == 1 else 1 if x == 2 else 0 for x in assign]

    return "YES\n" + " ".join(map(str, output))


