import math

def solve(n, a, b, arr):
    # Find all interesting divisors
    divisors = set()
    for x in arr:
        # For x, consider divisors of x, x-1, x+1
        if x - 1 > 1:
            divisors.update(get_prime_factors(x-1))
        divisors.update(get_prime_factors(x))
        if x + 1 > 1:
            divisors.update(get_prime_factors(x+1))

    ans = float('inf')

    # For each candidate divisor, compute cost
    for d in divisors:
        cost = compute_min_cost(n, a, b, arr, d)
        ans = min(ans, cost)

    return ans

def get_prime_factors(n):
    factors = set()
    d = 2
    temp = n
    while d * d <= temp:
        if temp % d == 0:
            factors.add(d)
            while temp % d == 0:
                temp //= d
        d += 1
    if temp > 1:
        factors.add(temp)
    return factors

def compute_min_cost(n, a, b, arr, d):
    # Compute cost for each element to be divisible by d
    costs = []
    for x in arr:
        rem = x % d
        if rem == 0:
            costs.append(0)
        elif rem == 1 or rem == d - 1:
            costs.append(b)
        else:
            costs.append(float('inf'))  # Cannot be made divisible with <= 1 change

    # Option 1: Remove nothing
    total = sum(costs)
    if any(c == float('inf') for c in costs):
        total = float('inf')
    ans = min(ans, total)

    # Option 2: Remove a segment
    # Use prefix sums to compute efficiently
    prefix_sum = [0] * (n + 1)
    for i in range(n):
        prefix_sum[i + 1] = prefix_sum[i] + costs[i]

    # Find min cost with one segment removal
    # If we remove [i, j], we pay (j-i+1)*a + sum of costs[k] for k in kept elements
    # = (j-i+1)*a + (total_sum - sum of costs from i to j)

    # Actually, let me think again: if we remove a segment, we can choose to remove
    # to avoid infinite costs. So if we have infinity costs, we need to handle that.

    # Check if possible without removal
    if total < float('inf'):
        ans = min(ans, total)

    # Now consider removal
    for i in range(n):
        for j in range(i, n):
            removal_cost = (j - i) * a  # number of elements removed is j-i+1, cost is (j-i+1)*a
            kept_cost = prefix_sum[0] + prefix_sum[i] + (prefix_sum[n] - prefix_sum[j+1] - prefix_sum[i])
            ans = min(ans, removal_cost + kept_cost)

import sys

MOD = 10**9 + 7

def solution(s):
    idx = 0
    n = len(s.strip())
    s = s.strip()

    # Helper to compute range concatenation
    def concat_range(l, r):
        res, cnt = 0, 0
        for i in range(l, r + 1):
            si = str(i)
            cnt += len(si)
            res = (res * pow(10, len(si), MOD) + int(si)) % MOD
        return res, cnt

    # Skip whitespace and peek ahead
    def skip():
        nonlocal idx
        while idx < n and s[idx] in ' \t':
            idx += 1

    def parse_number():
        nonlocal idx
        start = idx
        while idx < n and s[idx].isdigit():
            idx += 1
        return int(s[start:idx])

    # Flexible recursive descent parser
    def parse_term():
        nonlocal idx
        skip()
        l = parse_number()
        if idx < n and s[idx] == '-':
            idx += 1
            r = parse_number()
            return concat_range(l, r)
        if idx < n and s[idx] == '(':
            idx += 1
            v, c = parse_expr()
            idx += 1  # skip ')'
            return v, c * len(str(l))
        c = len(str(l))
        return l % MOD, c

    def parse_expr():
        nonlocal idx
        v, c = parse_term()
        while idx < n and s[idx] == '+':
            idx += 1
            t, tc = parse_term()
            v = (v * pow(10, tc, MOD) + t) % MOD
            c += tc
        return v, c

    # Main parsing
    v, c = parse_expr()
    return str(v % MOD)

def solution(input_str):
    n, k = map(int, input_str.strip().split())

    def invert(s):
        """Invert all bits: 0 -> 1, 1 -> 0"""
        return ''.join('1' if c == '0' else '0' for c in s)

    def get_canonical(s):
        """Get the lexicographically smallest string in the equivalence class"""
        transforms = [s, s[::-1], invert(s), invert(s)[::-1]]
        return min(transforms)

    def solve(n, k):
        """Find all unique canonical representatives for given n"""
        canonicals = set()
        # Generate all 2^n strings and find their canonical forms
        for i in range(1 << n):
            s = format(i, f'0{n}b')
            canonicals.add(get_canonical(s))

        sorted_canonicals = sorted(list(canonicals))

        if k > len(sorted_canonicals):
            return "-1"

        return sorted_canonicals[k-1] + "\n"

    return solve(n, k)

