def solution(input_str):
    lines = input_str.strip().split('\n')
    m = int(lines[0])

    def is_valid_set(a, b, set_num):
        """Check if a set score is valid according to volleyball rules"""
        diff = abs(a - b)
        if diff < 2:
            return False
        min_score = 15 if set_num == 5 else 25

        # Check if Team A can win this set
        a_wins = a >= min_score and a - b >= 2
        # Check if Team B can win this set  
        b_wins = b >= min_score and b - a >= 2

        if a_wins or b_wins:
            return True
        return False

    def search(a_wins_needed, b_wins_needed, a_rem, b_rem, set_num, current_sets, found_sets, max_found):
        """DFS to find valid set distributions"""
        if len(found_sets) >= max_found:
            return

        if set_num > 5:
            return

        if set_num == a_wins_needed + b_wins_needed and a_rem == 0 and b_rem == 0:
            found_sets.append(list(current_sets))
            return

        # Try Team A winning this set
        if a_wins_needed > 0 and set_num <= 5:
            # Generate possible scores where Team A wins
            if set_num == 5:  # 5th set
                min_a = 15
                min_b = 0
                for a in range(min(max(min_a, a_rem - 100), 15), min_a + b_rem + 20):
                    if a > a_rem:
                        break
                    for b in range(max(0, b_rem + 1)):
                        if b < a - 2:
                            continue
                        if is_valid_set(a, b, set_num):
                            if a_rem >= a and b_rem >= b:
                                new_sets = current_sets + [(a, b)]
                                new_a_rem = a_rem - a
                                new_b_rem = b_rem - b
                                search(a_wins_needed - 1, b_wins_needed, 
                                      new_a_rem, new_b_rem, set_num + 1, 
                                      new_sets, found_sets, max_found)
                                if len(found_sets) >= max_found:
                                    return
            else:  # Regular sets
                min_a = 25
                min_b = 0
                for a in range(min_a, min(max(a_rem, min_a), a_rem + 10)):
                    if a > a_rem:
                        break
                    for b in range(b_rem + 1):
                        if is_valid_set(a, b, set_num):
                            if a_rem >= a and b_rem >= b:
                                new_sets = current_sets + [(a, b)]
                                new_a_rem = a_rem - a
                                new_b_rem = b_rem - b
                                search(a_wins_needed - 1, b_wins_needed,
                                      new_a_rem, new_b_rem, set_num + 1,
                                      new_sets, found_sets, max_found)
                                if len(found_sets) >= max_found:
                                    return

        # Try Team B winning this set
        if b_wins_needed > 0 and set_num <= 5:
            if set_num == 5:
                min_b = 15
                min_a = 0
                for b in range(min(max(min_b, b_rem - 100), 15), min_b + a_rem + 20):
                    if b > b_rem:
                        break
                    for a in range(max(0, a_rem + 1)):
                        if is_valid_set(a, b, set_num):
                            if a_rem >= a and b_rem >= b:
                                new_sets = current_sets + [(a, b)]
                                new_a_rem = a_rem - a
                                new_b_rem = b_rem - b
                                search(a_wins_needed, b_wins_needed - 1,
                                      new_a_rem, new_b_rem, set_num + 1,
                                      new_sets, found_sets, max_found)
                                if len(found_sets) >= max_found:
                                    return
            else:
                min_b = 25
                min_a = 0
                for b in range(min(max(min_b, b_rem - 100), 25), min_b + a_rem + 20):
                    if b > b_rem:
                        break
                    for a in range(max(0, a_rem + 1)):
                        if is_valid_set(a, b, set_num):
                            if a_rem >= a and b_rem >= b:
                                new_sets = current_sets + [(a, b)]
                                new_a_rem = a_rem - a
                                new_b_rem = b_rem - b
                                search(a_wins_needed, b_wins_needed - 1,
                                      new_a_rem, new_b_rem, set_num + 1,
                                      new_sets, found_sets, max_found)
                                if len(found_sets) >= max_found:
                                    return

    results = []

    for i in range(1, len(lines)):
        parts = lines[i].split()
        a_total, b_total = int(parts[0]), int(parts[1])

        # Try outcomes in preference order (best for Team A first)
        outcomes = [
            (3, 0),  # Team A wins 3-0
            (3, 1),  # Team A wins 3-1
            (3, 2),  # Team A wins 3-2
            (2, 3),  # Team B wins 3-2
            (1, 3),  # Team B wins 3-1
            (0, 3),  # Team B wins 3-0
        ]

        best_outcome = "Impossible"
        best_sets = []

        for a_wins, b_wins in outcomes:
            found_sets = []
            search(a_wins, b_wins, a_total, b_total, 1, [], found_sets, 1)

            if found_sets:
                best_outcome = f"{a_wins}:{b_wins}"
                best_sets = found_sets[0]
                break

        if best_outcome != "Impossible":
            set_strs = " ".join(f"{x}:{y}" for x, y in best_sets)
            results.append(f"{best_outcome}\n{set_strs} ")
        else:
            results.append("Impossible")

    return "\n".join(results)
